package me.semmmetje.banditorders;
import net.milkbowl.vault.economy.Economy;import org.bukkit.*;import org.bukkit.command.*;import org.bukkit.configuration.file.YamlConfiguration;import org.bukkit.entity.Player;import org.bukkit.event.*;import org.bukkit.event.inventory.*;import org.bukkit.inventory.*;import org.bukkit.inventory.meta.ItemMeta;import org.bukkit.plugin.RegisteredServiceProvider;import org.bukkit.plugin.java.JavaPlugin;import java.io.*;import java.util.*;
public final class BanditOrders extends JavaPlugin implements Listener,CommandExecutor{
 record Order(String id,UUID buyer,Material item,int total,int remaining,double price){}
 private final Map<String,Order> orders=new LinkedHashMap<>();private Economy eco;private File file;private YamlConfiguration gui;
 public void onEnable(){saveDefaultConfig();saveResource("gui.yml",false);file=new File(getDataFolder(),"orders.yml");gui=YamlConfiguration.loadConfiguration(new File(getDataFolder(),"gui.yml"));hook();load();Objects.requireNonNull(getCommand("orders")).setExecutor(this);getServer().getPluginManager().registerEvents(this,this);}
 private void hook(){RegisteredServiceProvider<Economy> p=getServer().getServicesManager().getRegistration(Economy.class);if(p!=null)eco=p.getProvider();}
 private void load(){YamlConfiguration y=YamlConfiguration.loadConfiguration(file);for(String id:y.getKeys(false)){try{orders.put(id,new Order(id,UUID.fromString(y.getString(id+".buyer")),Material.valueOf(y.getString(id+".item")),y.getInt(id+".total"),y.getInt(id+".remaining"),y.getDouble(id+".price")));}catch(Exception ignored){}}}
 private void save(){YamlConfiguration y=new YamlConfiguration();for(Order o:orders.values()){String p=o.id;y.set(p+".buyer",o.buyer.toString());y.set(p+".item",o.item.name());y.set(p+".total",o.total);y.set(p+".remaining",o.remaining);y.set(p+".price",o.price);}try{y.save(file);}catch(IOException e){getLogger().warning(e.getMessage());}}
 public boolean onCommand(CommandSender s,Command c,String l,String[] a){if(!(s instanceof Player p))return true;if(a.length==0){list(p,0,"newest","");return true;}if(a[0].equalsIgnoreCase("create"))return create(p,a);if(a[0].equalsIgnoreCase("delete"))return delete(p,a);if(a[0].equalsIgnoreCase("search")&&a.length==2){list(p,0,"search",a[1].equalsIgnoreCase("hand")?p.getInventory().getItemInMainHand().getType().name():a[1]);return true;}if(a[0].equalsIgnoreCase("filter")&&a.length==2){list(p,0,a[1].toLowerCase(),"");return true;}if(a[0].equalsIgnoreCase("admin")&&p.hasPermission("banditorders.admin")){if(a.length>2&&a[1].equalsIgnoreCase("delete")){orders.remove(a[2]);save();p.sendMessage(color("&aOrder deleted."));return true;}if(a.length>1&&a[1].equalsIgnoreCase("reload")){reloadConfig();gui=YamlConfiguration.loadConfiguration(new File(getDataFolder(),"gui.yml"));hook();p.sendMessage(color("&aOrders reloaded."));return true;}}list(p,0,"newest","");return true;}
 private boolean create(Player p,String[] a){if(eco==null){msg(p,"no-economy",Map.of());return true;}if(a.length<4){msg(p,"invalid",Map.of());return true;}Material m=a[1].equalsIgnoreCase("hand")?p.getInventory().getItemInMainHand().getType():Material.matchMaterial(a[1].toUpperCase());int amount;double price;try{amount=Integer.parseInt(a[2]);price=Double.parseDouble(a[3]);}catch(Exception e){msg(p,"invalid",Map.of());return true;}if(m==null||m.isAir()||amount<1||!Double.isFinite(price)||price<=0){msg(p,"invalid",Map.of());return true;}long own=orders.values().stream().filter(o->o.buyer.equals(p.getUniqueId())).count();if(own>=getConfig().getInt("max-orders-per-player",10)){msg(p,"full",Map.of());return true;}double total=amount*price;if(!eco.has(p,total)){msg(p,"no-money",Map.of());return true;}eco.withdrawPlayer(p,total);Order o=new Order(UUID.randomUUID().toString().substring(0,8),p.getUniqueId(),m,amount,amount,price);orders.put(o.id,o);save();msg(p,"created",Map.of("amount",""+amount,"item",m.name()));return true;}
 private boolean delete(Player p,String[] a){if(a.length!=2){p.sendMessage("/orders delete <order-id>");return true;}Order o=orders.get(a[1]);if(o==null||!o.buyer.equals(p.getUniqueId())){p.sendMessage(color("&cOrder not found."));return true;}double refund=o.remaining*o.price;if(eco!=null)eco.depositPlayer(p,refund);orders.remove(o.id);save();msg(p,"deleted",Map.of("money",eco==null?""+refund:eco.format(refund)));return true;}
 private void list(Player p,int page,String filter,String query){Inventory inv=Bukkit.createInventory(new ListHolder(page,filter,query),54,color(gui.getString("list-title")));border(inv);List<Order> all=filtered(filter,query);for(int i=0;i<28&&page*28+i<all.size();i++){Order o=all.get(page*28+i);inv.setItem(content()[i],item(o.item,replace(gui.getString("order-name"),Map.of("item",nice(o.item))),gui.getStringList("order-lore").stream().map(x->replace(x,vars(o))).toList()));}p.openInventory(inv);}
 private void deliver(Player p,Order o){Inventory inv=Bukkit.createInventory(new DeliveryHolder(o.id),27,color(gui.getString("delivery-title")));border(inv);inv.setItem(gui.getInt("info-slot"),item(o.item,color("&#d9a441&l"+nice(o.item)),List.of(color("&7Place items below to deliver."),color("&7Remaining: &#d9a441"+o.remaining))));p.openInventory(inv);}
 @EventHandler public void click(InventoryClickEvent e){if(!(e.getWhoClicked() instanceof Player p))return;if(e.getInventory().getHolder() instanceof ListHolder h){e.setCancelled(true);int i=slotIndex(e.getRawSlot());List<Order> all=new ArrayList<>(orders.values());if(i>=0&&h.page*28+i<filtered(h.filter,h.query).size())deliver(p,filtered(h.filter,h.query).get(h.page*28+i));}else if(e.getInventory().getHolder() instanceof DeliveryHolder h){if(e.getRawSlot()<27&&!gui.getIntegerList("input-slots").contains(e.getRawSlot()))e.setCancelled(true);}}
 @EventHandler public void close(InventoryCloseEvent e){if(!(e.getInventory().getHolder() instanceof DeliveryHolder h)||!(e.getPlayer() instanceof Player p))return;Order o=orders.get(h.id);if(o==null)return;int delivered=0;for(int slot:gui.getIntegerList("input-slots")){ItemStack s=e.getInventory().getItem(slot);if(s!=null&&s.getType()==o.item){int take=Math.min(s.getAmount(),o.remaining-delivered);delivered+=take;s.setAmount(s.getAmount()-take);if(s.getAmount()==0)e.getInventory().setItem(slot,null);}}for(int slot:gui.getIntegerList("input-slots")){ItemStack s=e.getInventory().getItem(slot);if(s!=null&&!s.getType().isAir())p.getInventory().addItem(s);}if(delivered<1)return;double paid=delivered*o.price;if(eco!=null)eco.depositPlayer(p,paid);int left=o.remaining-delivered;if(left<=0)orders.remove(o.id);else orders.put(o.id,new Order(o.id,o.buyer,o.item,o.total,left,o.price));save();msg(p,"paid",Map.of("amount",""+delivered,"item",nice(o.item),"money",eco==null?""+paid:eco.format(paid)));}
 record ListHolder(int page,String filter,String query)implements InventoryHolder{public Inventory getInventory(){return null;}}record DeliveryHolder(String id)implements InventoryHolder{public Inventory getInventory(){return null;}}
 private List<Order> filtered(String filter,String query){List<Order> out=new ArrayList<>(orders.values());if(filter.equals("search"))out.removeIf(o->!o.item.name().equalsIgnoreCase(query));if(filter.equals("delivered"))out.sort(Comparator.comparingInt((Order o)->o.total-o.remaining).reversed());else if(filter.equals("price"))out.sort(Comparator.comparingDouble((Order o)->o.price).reversed());else if(filter.equals("oldest"))Collections.reverse(out);return out;}private int[] content(){return new int[]{10,11,12,13,14,15,16,19,20,21,22,23,24,25,28,29,30,31,32,33,34,37,38,39,40,41,42,43};}private int slotIndex(int slot){int[] slots=content();for(int i=0;i<slots.length;i++)if(slots[i]==slot)return i;return -1;}private void border(Inventory i){Material b=Material.matchMaterial(gui.getString("border","BLACK_STAINED_GLASS_PANE"));for(int x=0;x<i.getSize();x++)if(x<9||x>=i.getSize()-9||x%9==0||x%9==8)i.setItem(x,item(b==null?Material.BLACK_STAINED_GLASS_PANE:b," ",List.of()));}private Map<String,String> vars(Order o){return Map.of("buyer",Bukkit.getOfflinePlayer(o.buyer).getName()==null?"Unknown":Bukkit.getOfflinePlayer(o.buyer).getName(),"remaining",""+o.remaining,"total",""+o.total,"price",eco==null?""+o.price:eco.format(o.price));}private ItemStack item(Material m,String n,List<String> l){ItemStack s=new ItemStack(m);ItemMeta x=s.getItemMeta();x.setDisplayName(color(n));x.setLore(l.stream().map(this::color).toList());s.setItemMeta(x);return s;}private String replace(String x,Map<String,String> v){for(var e:v.entrySet())x=x.replace("%"+e.getKey()+"%",e.getValue());return x;}private String nice(Material m){return Arrays.stream(m.name().split("_")).map(x->x.substring(0,1)+x.substring(1).toLowerCase()).reduce((a,b)->a+" "+b).orElse(m.name());}private String color(String s){return ChatColor.translateAlternateColorCodes('&',s);}private void msg(Player p,String k,Map<String,String> v){String s=getConfig().getString("messages."+k,"");for(var e:v.entrySet())s=s.replace("%"+e.getKey()+"%",e.getValue());p.sendMessage(color(s.replace("%prefix%",getConfig().getString("messages.prefix",""))));}}
